# The SDK and core class hierarchies are independent (the SDK cannot import core),
# so both carry the same author-facing definitions; the scheduling logic lives in
# the core copy at ``airflow.partition_mappers.wait_policy``. These SDK variants
# only need construction, equality, hashing, and repr so authored Dags can be
# compared and serialized.
from __future__ import annotations


class WaitPolicy:
    """Author-facing base for rollup wait policies. Carries no scheduling logic."""


class WaitForAll(WaitPolicy):
    """Fire only when every expected upstream key has arrived. Stateless."""

    def __repr__(self) -> str:
        return "WaitForAll()"

    def __eq__(self, other: object) -> bool:
        if not isinstance(other, WaitForAll):
            return NotImplemented
        return True

    def __hash__(self) -> int:
        return hash(WaitForAll)


class MinimumCount(WaitPolicy):
    """Fire once a threshold number of upstream keys have arrived."""

    def __init__(self, n: int) -> None:
        if n == 0:
            raise ValueError("MinimumCount(0) is degenerate: it would fire before any key arrives")
        self.n = n

    def __repr__(self) -> str:
        return f"MinimumCount(n={self.n})"

    def __eq__(self, other: object) -> bool:
        if not isinstance(other, MinimumCount):
            return NotImplemented
        return self.n == other.n

    def __hash__(self) -> int:
        return hash((MinimumCount, self.n))
